<script lang="ts">
  import ChartFrame from '@/components/ChartFrame.svelte';
  import DataTable from '@/components/DataTable.svelte';
  import RunnerReference from '@/pages/competitive/RunnerReference.svelte';
  import {simulatorResults,simulatorFinishDistributions,simulatorMatchups} from './simulator-results';
  import type {MonteCarloResult} from './simulator-repository';
  import {simulatorTeamColor,simulatorTeamLabel} from './simulator-roster.svelte';
  import type {SimulatorUma} from './simulator-uma';
  let {result,umas,onselect}:{result:MonteCarloResult;umas:SimulatorUma[];onselect?:(source:number)=>void}=$props();
  const metrics=$derived(simulatorResults(result,umas.length)),distributions=$derived(simulatorFinishDistributions(result,umas.length)),matchups=$derived(simulatorMatchups(result,umas.length));
  const bySource=$derived(new Map(metrics.map(row=>[row.source,row]))),byTime=$derived(new Map(distributions.runners.map(row=>[row.source,row])));
  const rows=$derived(metrics.map(row=>({id:row.source,name:umas[row.source]!.name,rate:row.winRate,top3:row.top3,place:row.place??0,time:row.time??0,inspect:''})));
  const x=(value:number)=>(value-distributions.min)/(distributions.max-distributions.min)*300;
  const signed=(value:number)=>(value>0?'+':'')+value.toFixed(3);
  const format=(value:number|undefined|null,digits=2)=>value==null?'—':value.toFixed(digits);
</script>
<section class="outcome" aria-label="Monte Carlo outcome">
  <ChartFrame plain surface id="simulator-field-outcomes" title="The field, compared" description="All sampled races. Compare win chance, podium consistency and finish-time spread together.">
    <DataTable caption="Monte Carlo runner outcomes" plain compact {rows} columns={[{key:'name',label:'Uma'},{key:'rate',label:'Win chance',numeric:true},{key:'top3',label:'Top 3',numeric:true},{key:'place',label:'Avg. place',numeric:true},{key:'time',label:'Finish time (s)',numeric:true},{key:'inspect',label:'Details',sortable:false}]} columnHelp={{'Win chance':'Observed win rate, wins / sampled races. The range is a 95% Wilson interval for sampling uncertainty.','Top 3':'Share of races finishing in the first three positions.','Avg. place':'Mean finishing position. Lower is better.','Finish time (s)':'Mean finish time, followed by median and the middle 80% of observed finish times. Lower is faster.'}}>
      {#snippet cell(row,column)}{@const metric=bySource.get(Number(row.id))!}{@const times=byTime.get(Number(row.id))!}
        {#if column.key==='name'}<div class="runner-cell"><RunnerReference name={row.name as string} cardId={umas[Number(row.id)]!.cardId}/><small><i class="team-dot" style:background={umas[Number(row.id)]!.teamColor??simulatorTeamColor(umas[Number(row.id)]!.teamId)}></i>{simulatorTeamLabel(umas[Number(row.id)]!.teamId,umas[Number(row.id)]!.teamColor)} · {metric.wins} wins</small></div>
        {:else if column.key==='rate'}<div class="win"><strong>{metric.winRate.toFixed(1)}%</strong><small>{metric.interval[0].toFixed(1)}–{metric.interval[1].toFixed(1)}%</small><span class="rate-bar"><i style:width={metric.winRate+'%'}></i></span></div>
        {:else if column.key==='top3'}{metric.top3.toFixed(1)}%
        {:else if column.key==='place'}{Number(row.place).toFixed(2)}
        {:else if column.key==='time'}<div class="time-cell"><strong>{times.mean.toFixed(3)}</strong><small>Median {times.median.toFixed(3)}</small><small>80%: {times.p10.toFixed(3)}–{times.p90.toFixed(3)}</small></div>
        {:else if column.key==='inspect'}<button class="inspect" aria-label={'Inspect '+row.name} onclick={()=>onselect?.(Number(row.id))}>Details →</button>{/if}
      {/snippet}
    </DataTable>
    <p class="note">Win intervals describe sampling uncertainty. The middle 80% describes race-to-race variation; they measure different things.</p>
  </ChartFrame>
  <div class="matrix-grid">
    <ChartFrame plain surface id="report-placement" title="Every finishing position" description="Percentage of races in each place. Read across a row to see consistency, including finishes outside the podium.">
      <!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables must be reachable with the keyboard.) -->
      <div class="matrix-scroll" role="region" aria-label="Placement distribution scroll area" tabindex="0"><table class="matrix placement"><caption>Placement distributions across all {result.runs} races</caption><thead><tr><th scope="col">Runner</th>{#each umas as _,place}<th scope="col">{place+1}</th>{/each}</tr></thead><tbody>{#each metrics as metric}<tr><th scope="row"><RunnerReference name={umas[metric.source]!.name} cardId={umas[metric.source]!.cardId} compact/></th>{#each metric.finishes as count,place}<td class:podium={place<3 && count>0} title={count+' of '+result.runs+' races'}>{count?(count/result.runs*100).toFixed(1)+'%':'—'}</td>{/each}</tr>{/each}</tbody></table></div>
      <p class="note">Each row totals 100%. A dash means no observed finishes in that place.</p>
    </ChartFrame>
    <ChartFrame plain surface id="report-matchups" title="Runner against runner" description="How often the row runner finished ahead of the column runner, paired within the same race. The smaller number is the mean time difference.">
      <!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables must be reachable with the keyboard.) -->
      <div class="matrix-scroll" role="region" aria-label="Head-to-head comparisons scroll area" tabindex="0"><table class="matrix matchups"><caption>Paired head-to-head results across all {result.runs} races</caption><thead><tr><th scope="col">Runner</th>{#each metrics as metric,rank}<th scope="col" title={umas[metric.source]!.name}>{rank+1}</th>{/each}</tr></thead><tbody>{#each metrics as metric,rank}<tr><th scope="row"><span class="runner-number">{rank+1}</span><RunnerReference name={umas[metric.source]!.name} cardId={umas[metric.source]!.cardId} compact/></th>{#each metrics as opponent}{@const pair=matchups[metric.source]![opponent.source]}<td>{#if pair}<span title={umas[metric.source]!.name+' finished ahead of '+umas[opponent.source]!.name+' in '+pair.ahead+' / '+result.runs+' races; 95% interval '+pair.interval[0].toFixed(1)+'–'+pair.interval[1].toFixed(1)+'%'}><strong class:advantage={pair.rate>50}>{pair.rate.toFixed(0)}%</strong><small>{signed(pair.gap)} s</small></span>{:else}<span class="diagonal">—</span>{/if}</td>{/each}</tr>{/each}</tbody></table></div>
      <p class="note">Negative time differences mean the row runner was faster. Column numbers match the runners listed at left.</p>
    </ChartFrame>
  </div>
  <ChartFrame plain surface id="report-finish-times" title="Finish-time distributions" description="Every runner on the same time scale. Bars are observed frequencies; the dashed line is the mean and the solid line is the median.">
    <p class="distribution-scale">Horizontal: finish time in seconds · Vertical: races per bin, shared maximum {distributions.peak}.</p>
    <div class="finish-grid">{#each distributions.runners as times}
      <article class="finish-card"><header><RunnerReference name={umas[times.source]!.name} cardId={umas[times.source]!.cardId} compact/><span>{times.mean.toFixed(3)} s <small>mean</small></span></header>
        <svg viewBox="0 0 300 96" preserveAspectRatio="none" role="img" aria-label={umas[times.source]!.name+' observed finish times. Mean '+times.mean.toFixed(3)+', median '+times.median.toFixed(3)+', fastest '+times.min.toFixed(3)+', slowest '+times.max.toFixed(3)+' seconds.'}>
          <line x1="0" x2="300" y1="80" y2="80" class="baseline"/>
          {#each times.bins as count,bin}<rect x={bin/times.bins.length*300+.5} y={80-count/distributions.peak*70} width={Math.max(1,300/times.bins.length-1)} height={count/distributions.peak*70} class="histogram"><title>{count} races · {(distributions.min+(distributions.max-distributions.min)*bin/times.bins.length).toFixed(2)}–{(distributions.min+(distributions.max-distributions.min)*(bin+1)/times.bins.length).toFixed(2)} s</title></rect>{/each}
          <line x1={x(times.mean)} x2={x(times.mean)} y1="4" y2="80" class="mean"/><line x1={x(times.median)} x2={x(times.median)} y1="4" y2="80" class="median"/>
          <text x="0" y="94">{distributions.min.toFixed(1)} s</text><text x="300" y="94" text-anchor="end">{distributions.max.toFixed(1)} s</text>
        </svg>
        <dl class="finish-stats"><div><dt>Fastest</dt><dd>{times.min.toFixed(3)}</dd></div><div><dt>Median</dt><dd>{times.median.toFixed(3)}</dd></div><div><dt>Slowest</dt><dd>{times.max.toFixed(3)}</dd></div><div><dt>Std. dev.</dt><dd>{times.sd.toFixed(3)}</dd></div></dl>
        <p class="range-note">Middle 80%: {times.p10.toFixed(3)}–{times.p90.toFixed(3)} s</p>
      </article>
    {/each}</div>
  </ChartFrame>
  <ChartFrame plain surface id="report-stamina" title="Stamina and the final spurt" description="Finish HP and spurt decisions for the entire batch. These explain stamina reliability alongside finishing performance.">
    <div class="energy-grid">{#each metrics as metric}<article class="energy-card"><header><RunnerReference name={umas[metric.source]!.name} cardId={umas[metric.source]!.cardId} compact/><strong>{format(metric.fullSpurt,1)}{metric.fullSpurt!==null?'%':''}<small>full spurt</small></strong></header>
      <dl><div><dt>Mean finish HP</dt><dd>{format(metric.hp,0)}</dd></div><div><dt>Finish HP, middle 80%</dt><dd>{metric.hpSummary?format(metric.hpSummary.p10,0)+'–'+format(metric.hpSummary.p90,0):'—'}</dd></div><div><dt>Finished at ≤0 HP</dt><dd class:depleted={metric.depleted!==null&&metric.depleted>0}>{format(metric.depleted,1)}{metric.depleted!==null?'%':''}</dd></div></dl>
      <div class="spurt-decisions">{#each metric.spurtCounts as entry}<span title={({1:'Full with spare HP',2:'Full',4:'Below minimum',8:'Reduced'})[entry.decision as 1|2|4|8]}>{({1:'Full + spare',2:'Full',4:'Below min.',8:'Reduced'})[entry.decision as 1|2|4|8]}<b>{result.last_spurt_decisions?entry.count:'—'}</b></span>{/each}</div>
    </article>{/each}</div>
    <p class="note">Full spurt combines “full” and “full with spare HP”. Finish HP does not identify the moment a runner exhausted; inspect a sampled replay for that sequence.</p>
  </ChartFrame>
</section>
<style>
  .outcome{display:grid;gap:16px;min-width:0}.runner-cell{display:grid;gap:3px}.team-dot{display:inline-block;width:7px;height:7px;border-radius:2px;margin-right:5px}.runner-cell>small{font-size:10px;color:var(--text-secondary);margin-left:34px}.win{display:grid;gap:4px;min-width:104px;max-width:170px;margin-left:auto}.win strong{font-size:13px}.win small,.time-cell small{font-size:10px;color:var(--text-secondary)}.rate-bar{height:3px;background:var(--surface-3);border-radius:2px;overflow:hidden}.rate-bar i{display:block;height:100%;background:var(--accent-primary)}.time-cell{display:grid;gap:4px}.time-cell>strong{font-size:12px;font-weight:600}.inspect{border:0;background:transparent;color:var(--accent-primary);padding:8px 0;cursor:pointer;font:inherit;font-size:11px;white-space:nowrap}.inspect:focus-visible{outline:2px solid var(--accent-primary)}.outcome :global(.runner-reference .art){width:26px;height:32px}.outcome :global(.runner-name strong){font-size:12px}.outcome :global(.compact td){padding:9px 8px}.note{font-size:10px;line-height:1.7;color:var(--text-secondary);margin:10px 0 0}.matrix-grid{display:grid;gap:16px;min-width:0}.matrix-grid> :global(.chart-frame){min-width:0}.matrix-scroll{overflow:auto;max-width:100%;scrollbar-width:thin}.matrix{border-collapse:collapse;width:100%;font-size:11px;font-variant-numeric:tabular-nums}.matrix caption{position:absolute;width:1px;height:1px;clip-path:inset(50%);overflow:hidden}.matrix th,.matrix td{border-bottom:1px solid var(--border-subtle);padding:8px 6px;text-align:right;white-space:nowrap}.matrix thead th{font-size:10px;font-weight:500;color:var(--text-secondary);height:28px}.matrix th:first-child{text-align:left;position:sticky;left:0;z-index:1;background:var(--surface-1);min-width:150px}.matrix tbody th:first-child{display:flex;align-items:center;gap:7px;font-weight:400}.matrix td{min-width:48px}.matrix td.podium,.advantage{color:var(--accent-primary)}.matrix td>span{display:grid;gap:4px}.matrix td strong{font-weight:500}.matrix td small{font-size:9px;color:var(--text-secondary)}.runner-number{font-size:10px;color:var(--text-secondary);min-width:12px}.diagonal{opacity:.35}.distribution-scale{font-size:10px;line-height:1.7;color:var(--text-secondary);margin:0 0 12px}.finish-grid,.energy-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.finish-card,.energy-card{min-width:0;padding:12px;border:1px solid var(--border-subtle);border-radius:var(--radius-md)}.finish-card header,.energy-card header{display:flex;align-items:center;justify-content:space-between;gap:8px}.finish-card header>span{font-size:12px;font-variant-numeric:tabular-nums;white-space:nowrap}.finish-card header>span small{font-size:9px;color:var(--text-secondary)}.finish-card svg{width:100%;height:100px;display:block;margin:10px 0}.histogram{fill:var(--accent-primary);fill-opacity:.45}.baseline{stroke:var(--border-subtle)}.mean{stroke:var(--text-primary);stroke-dasharray:4 3;stroke-width:1.2}.median{stroke:var(--accent-primary);stroke-width:1.5}text{fill:var(--text-secondary);font-size:9px}.finish-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin:0}.finish-stats dt{font-size:9px;color:var(--text-secondary)}.finish-stats dd{margin:5px 0 0;font-size:11px;font-variant-numeric:tabular-nums}.range-note{font-size:10px;color:var(--text-secondary);margin:10px 0 0}.energy-card header>strong{font-size:15px;text-align:right;font-weight:600;white-space:nowrap}.energy-card header>strong small{display:block;margin-top:3px;font-size:9px;color:var(--text-secondary);font-weight:400}.energy-card>dl{display:grid;gap:8px;margin:14px 0}.energy-card>dl>div{display:flex;justify-content:space-between;gap:10px}.energy-card dt{font-size:10px;color:var(--text-secondary)}.energy-card dd{margin:0;font-size:11px;font-variant-numeric:tabular-nums}.depleted{color:var(--color-warning)}.spurt-decisions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;padding-top:10px;border-top:1px solid var(--border-subtle)}.spurt-decisions>span{display:flex;justify-content:space-between;gap:8px;font-size:9px;color:var(--text-secondary)}.spurt-decisions b{font-size:10px;font-weight:500;color:var(--text-primary)}
  @container race-main (min-width:1250px){.matrix-grid{grid-template-columns:1fr 1fr}}
  @container race-main (max-width:1000px){.finish-grid,.energy-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
  @media(max-width:600px){.finish-grid,.energy-grid{grid-template-columns:minmax(0,1fr)}.win{min-width:86px}.matrix th:first-child{min-width:138px}.matrix td{min-width:46px}.outcome :global(.table-wrap>table){display:block}.outcome :global(.table-wrap>table>thead){display:none}.outcome :global(.table-wrap>table>tbody){display:grid}.outcome :global(.table-wrap>table>tbody>tr:not([aria-hidden])){display:grid;grid-template-columns:1fr 1fr;padding:12px 0;border-bottom:1px solid var(--border-subtle)}.outcome :global(.table-wrap td){display:block;min-width:0;white-space:normal;text-align:left;border:0;padding:6px 0}.outcome :global(.table-wrap td:before){content:attr(data-label);display:block;font-size:9px;color:var(--text-secondary);margin-bottom:5px}.outcome :global(.table-wrap td:first-child),.outcome :global(.table-wrap td:last-child){grid-column:1/-1}.outcome :global(.table-wrap td:first-child:before),.outcome :global(.table-wrap td:last-child:before){display:none}.win{margin-left:0;max-width:140px}.runner-cell>small{margin-left:32px}}
</style>
